import{z as m,x as p,o as r,c as B,q as l,j as o,D as t,d as s,s as n,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"Lucas 树","description":"","frontmatter":{"title":"Lucas 树","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/lucas-tree.md","filePath":"econ/lucas-tree.md","lastUpdated":1791413859000}'),u={name:"econ/lucas-tree.md"};function c(A,a,d,y,D,h){const E=p("Mermaid");return r(),B("div",null,[a[2]||(a[2]=l('<h1 id="lucas-树" tabindex="-1">Lucas 树 <a class="header-anchor" href="#lucas-树" aria-label="Permalink to &quot;Lucas 树&quot;">​</a></h1><div class="epigraph"><p>果实外生落下，证券是对果实的要求权；价格使代表性主体愿意持有这棵树，随机折现因子就是果实的边际效用比。</p><footer>—— Lucas, Asset Prices in an Exchange Economy, Econometrica, 1978</footer></div><p><a href="/econ/state-price-sdf-bridge">上一课</a>焊好了 \\(q\\)、\\(m\\)、\\(\\mathbb{Q}\\)。本课缺口是<strong>均衡选取</strong>：在纯交换的禀赋经济里，消费等于树上落下的果实，\\(m\\) 不再是任意正核，而是 \\(\\beta u&#39;(y_{t+1})/u&#39;(y_t)\\)。不重写 FTAP，不把 Mehra–Prescott 的校准表提前铺开——谜是特化失败，树是装置。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Lucas（1978）：Markov 果实过程 \\(\\{y_t\\}\\)，代表性主体、完全市场、无生产。股权是对全部果实的要求权，债券是对确定支付的要求权。出清迫使 \\(c_t=y_t\\)，欧拉成为定价方程。价格是果实流在该核下的期望折现。缺口不是再定义 SDF，而是：无套利允许许多 \\(m\\)，出清加代表性主体选出一个，并且把选出的 \\(m\\) 绑在可观测的总量 \\(y\\) 上。</p><p>这与 <a href="/econ/capm-theory">CAPM</a> 的选取不同：CAPM 用均值方差加总把 \\(m\\) 绑在市场回报上；Lucas 树把 \\(m\\) 绑在禀赋边际效用上。两者都可以是完全市场均衡，坐标不同。CCAPM 是连续时间里把消费当充分统计；树是离散 Markov 的教室版。</p><p><span class="marginnote">Lucas, <em>Econometrica</em> 46(6), 1978。果实外生，故称交换经济。生产课序会让 \\(y\\) 对价格有反馈，那是 Cochrane 的生产基础定价，不是本课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Bellman 或直接欧拉。股权价格 \\(p_t=p(y_t)\\) 满足</p> \\[p(y)=\\mathrm{E}\\Bigl[\\beta\\frac{u&#39;(y&#39;)}{u&#39;(y)}\\bigl(y&#39;+p(y&#39;)\\bigr)\\Bigm|y\\Bigr]. \\]<p>无风险利率由 \\(\\mathrm{E}[m\\mid y]\\) 的倒数给出。Markov 使价格是 \\(y\\) 的函数，不必另引泡沫项——横截条件把爆炸解关掉（理性泡沫课已从行为课序写过另一条缝）。本课默认基本面解。</p>',11)),(r(),o(i,null,{default:t(()=>[n(E,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20Y%5B%22%E6%9E%9C%E5%AE%9E%20y%20%3D%20%E6%B6%88%E8%B4%B9%22%5D%20--%3E%20M%5B%22m%20%3D%20%CE%B2%20u'(y')%2Fu'(y)%22%5D%0A%20%20M%20--%3E%20P%5B%22p%20%3D%20E%5Bm%20(y'%2Bp')%5D%22%5D%0A%20%20P%20--%3E%20RF%5B%22Rf%20%3D%201%2FE%5Bm%5D%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与信息课序：树通常假定公共信息，价格完全反映 \\(y\\) 的历史，没有 GS 采集。把果实做成私人观察，REE 与树可以叠，本课不叠，以免装置失焦。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"数字实例：取 \\(\\beta=0.96\\)、CRRA 效用且风险厌恶 \\(\\gamma=2\\)，若明年果实是今年的两倍，\\(u'(y')/u'(y)=(2)^{-2}=0.25\\)，于是 \\(m\\approx 0.96\\times 0.25=0.24\\)。果实越丰收，\\(m\\) 越小——「下一单位果实」在你最不缺时最不值钱，这正是核随景气反向变动的含义。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"机制是代表性主体必须愿意持有全部风险。没有外部，果实的波动就是消费波动，\\(u'\\) 的波动就是 \\(m\\) 的波动。果实高的状态 \\(m\\) 低，股权在那时支付高，协方差为负，故有正溢价。债券在所有状态支付确定，溢价为零（实际债券），名义债券另论。股权溢价之谜已经在主干里：观测到的 \\(y\\) 太平，常规 \\(u\\) 给不出够抖的 \\(m\\)。本课只把机制钉在树上，不重跑校准。",-1)),(r(),o(i,null,{default:t(()=>[n(E,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E6%9E%9C%E5%AE%9E%E5%A5%BD%E7%9A%84%E7%8A%B6%E6%80%81%20y%20%E9%AB%98%22%5D%20--%3E%20B%5B%22u'(y)%20%E4%BD%8E%22%5D%0A%20%20B%20--%3E%20C%5B%22m%20%3D%20%CE%B2u'%2Fu'%20%E4%BD%8E%22%5D%0A%20%20C%20--%3E%20D%5B%22%E8%82%A1%E6%9D%83%E6%81%B0%E5%9C%A8%E6%AD%A4%E6%97%B6%E6%94%AF%E4%BB%98%E5%A4%9A%22%5D%0A%20%20D%20--%3E%20E%5B%22%E6%94%AF%E4%BB%98%E4%B8%8E%20m%20%E8%B4%9F%E5%8D%8F%E6%96%B9%E5%B7%AE%22%5D%0A%20%20E%20--%3E%20F%5B%22%E5%BF%85%E9%A1%BB%E7%BB%99%E6%AD%A3%E6%BA%A2%E4%BB%B7%E6%89%8D%E6%9C%89%E4%BA%BA%E6%8C%81%E6%9C%89%22%5D%0A%20%20G%5B%22%E6%9E%9C%E5%AE%9E%E5%B7%AE%E7%9A%84%E7%8A%B6%E6%80%81%20y%20%E4%BD%8E%22%5D%20--%3E%20H%5B%22u'(y)%20%E9%AB%98%22%5D%0A%20%20H%20--%3E%20I%5B%22m%20%E9%AB%98%22%5D%0A%20%20I%20--%3E%20E%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p>生产一旦进来，\\(c\\) 可以平滑，\\(y\\) 不再等于 \\(c\\)，核跟着消费走而不是跟着股利走——后课生产基础会反过来用投资的一阶条件给回报定价。树是无平滑技术的对照。</p><p><span class="marginnote">直觉类比：股权像一张「丰收时才兑付」的粮票——兑现的时刻恰恰是人人粮食充裕、多一单位粮食最不值钱的时候。一个总在你最不需要时才给你钱的资产，没人愿意出高价买，只能打折出售；这个价格折扣在持有期回报上就表现为持续的正溢价。</span></p><p><span class="marginnote">异质主体、不完全市场会让 \\(m\\) 依赖某个加权消费或约束乘子，不再等于总量 \\(u&#39;(y)\\)。树是加总已经完成的特例。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把树写成「股利贴现模型的实证」。后课 Campbell–Shiller 才把价格、股利、回报做成恒等式与预测。本课价格是均衡函数 \\(p(y)\\)，不是回归。也不要把树的 Markov 当成限价簿上的状态变量。</p><p><span class="marginnote">常见误区：初学者容易把本课的 \\(p(y)\\) 看成「股利贴现模型的一个算例」。实际上 DDM 里折现率是外生拍定的参数，怎么选都行；树里的折现核 \\(m\\) 是由「消费必须等于果实」这一出清条件内生决定的均衡对象——同一份果实用不同的 \\(u\\)、\\(\\beta\\) 会解出不同的 \\(p(y)\\)，这才是「基础定价」的意思。</span></p><p>下一课：在不指定 \\(u\\) 的前提下，把价格、股利与回报的对数线性关系写成会计恒等式——Campbell–Shiller 分解。树给出的 \\(p(y)\\) 必须服从那条会计。</p><p>后课默认：交换经济出清 ⇒ \\(c=y\\) ⇒ \\(m\\) 由果实的边际效用给出。这是对 FTAP 集合的均衡选取，不是对 NA 的替代定义。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Lucas 树：外生果实，出清 \\(c=y\\)，股权是对果实的要求权。</li><li>\\(m=\\beta u&#39;(y&#39;)/u&#39;(y)\\) 是均衡选出的核，价格是该核下的期望折现。</li><li>溢价之谜是这个特化在数据上抖不够，不是树的定义失败。</li><li>出处：Lucas, <em>Econometrica</em> 1978。</li></ul>',10))])}const f=m(u,[["render",c]]);export{b as __pageData,f as default};
